package com.carparts.platform.workflow;

import com.carparts.platform.auth.AuthPrincipal;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.sql.*;
import java.time.*;
import java.util.*;

@Service
public class WorkflowService {
    private final JdbcTemplate jdbc; public WorkflowService(JdbcTemplate jdbc){this.jdbc=jdbc;}
    public record TagRow(UUID id,String slug,String labelFa,String colorKey,String source){}
    public record CaseRow(UUID id,long caseNo,long requestNo,String source,String contactName,String contactPhone,String requestedPartNumber,String requestText,String vehicleText,UUID productId,String stage,String priority,String agreementStatus,Instant nextActionAt,String notes,Instant updatedAt,List<TagRow> tags){}
    public record Overview(long openCases,long newRequests,long sourcing,long waitingCustomer,long shipping,long customs,long delivered,long unreadContacts){}
    public record CreateRequest(String source,String contactName,String contactPhone,String contactEmail,String requestedPartNumber,String requestText,String vehicleText,String priority,UUID productId){}
    public record Transition(String stage,String note,String agreementStatus,Instant nextActionAt){}
    public record SupplierQuoteInput(UUID supplierId,String supplierName,String country,String currency,BigDecimal unitPrice,BigDecimal quantity,BigDecimal foreignTransport,BigDecimal internationalShipping,BigDecimal availableQuantity,Integer leadDays,LocalDate validUntil){}
    public record CustomerQuoteInput(String currency,BigDecimal supplierCost,BigDecimal logisticsCost,BigDecimal customsCost,BigDecimal bankCost,BigDecimal localCost,BigDecimal otherCost,BigDecimal markupAmount,BigDecimal discountAmount,BigDecimal taxAmount,BigDecimal exchangeRate,BigDecimal totalPrice,LocalDate validUntil,boolean sendNow){}
    public record CaseDetail(CaseRow caseInfo,List<Map<String,Object>> supplierQuotes,List<Map<String,Object>> customerQuotes,List<Map<String,Object>> events){}

    public Overview overview(){return new Overview(count("SELECT COUNT(*) FROM workflow_cases WHERE stage NOT IN ('CLOSED','CANCELLED','DELIVERED')"),count("SELECT COUNT(*) FROM workflow_cases WHERE stage='REQUESTED'"),count("SELECT COUNT(*) FROM workflow_cases WHERE stage IN ('PRODUCT_CREATED','SOURCING','SUPPLIER_QUOTED','INTERNAL_COSTED')"),count("SELECT COUNT(*) FROM workflow_cases WHERE stage='CUSTOMER_QUOTED'"),count("SELECT COUNT(*) FROM workflow_cases WHERE stage IN ('SUPPLIER_ORDERED','IN_TRANSIT','LOCAL_WAREHOUSE','READY_FOR_DELIVERY')"),count("SELECT COUNT(*) FROM workflow_cases WHERE stage='CUSTOMS'"),count("SELECT COUNT(*) FROM workflow_cases WHERE stage IN ('DELIVERED','CLOSED')"),count("SELECT COUNT(*) FROM contact_messages WHERE status='NEW'"));}
    public List<CaseRow> cases(String stage){String base="SELECT c.id,c.case_no,r.request_no,r.source,r.contact_name,r.contact_phone,r.requested_part_number,r.request_text,r.vehicle_text,c.product_id,c.stage,c.priority,c.agreement_status,c.next_action_at,c.notes,c.updated_at FROM workflow_cases c JOIN customer_requests r ON r.id=c.request_id ";String order=" ORDER BY CASE c.priority WHEN 'URGENT' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'NORMAL' THEN 3 ELSE 4 END,c.updated_at DESC LIMIT 300";return stage==null||stage.isBlank()?jdbc.query(base+order,this::mapCase):jdbc.query(base+"WHERE c.stage=?"+order,this::mapCase,stage);}
    public CaseDetail detail(UUID id){CaseRow info=required(id);return new CaseDetail(info,jdbc.queryForList("SELECT id,supplier_name_snapshot,country,currency,unit_price,quantity,foreign_transport,international_shipping,available_quantity,lead_days,valid_until,status,quoted_at FROM supplier_quotes WHERE case_id=? ORDER BY quoted_at DESC",id),jdbc.queryForList("SELECT id,quote_no,currency,supplier_cost,logistics_cost,customs_cost,bank_cost,local_cost,other_cost,markup_amount,discount_amount,tax_amount,exchange_rate,total_price,valid_until,status,created_at FROM customer_quotes WHERE case_id=? ORDER BY created_at DESC",id),jdbc.queryForList("SELECT event_type,from_stage,to_stage,note,payload,created_at FROM workflow_events WHERE case_id=? ORDER BY created_at DESC LIMIT 100",id));}

    @Transactional public CaseRow createManual(CreateRequest in,AuthPrincipal actor){return create(in,actor.id(),false);}
    @Transactional public CaseRow createSite(CreateRequest in){return create(new CreateRequest("SITE",in.contactName(),in.contactPhone(),in.contactEmail(),in.requestedPartNumber(),in.requestText(),in.vehicleText(),in.priority(),in.productId()),null,true);}
    @Transactional public CaseRow transition(UUID caseId,Transition in,AuthPrincipal actor){Set<String> allowed=Set.of("REQUESTED","PRODUCT_CREATED","SOURCING","SUPPLIER_QUOTED","INTERNAL_COSTED","CUSTOMER_QUOTED","CUSTOMER_AGREED","SUPPLIER_ORDERED","IN_TRANSIT","CUSTOMS","LOCAL_WAREHOUSE","READY_FOR_DELIVERY","DELIVERED","CLOSED","CANCELLED");if(in.stage()==null||!allowed.contains(in.stage()))throw bad("مرحله نامعتبر است.");CaseRow old=required(caseId);String agreement=in.agreementStatus()==null?old.agreementStatus():in.agreementStatus();jdbc.update("UPDATE workflow_cases SET stage=?,agreement_status=?,next_action_at=?,updated_at=NOW() WHERE id=?",in.stage(),agreement,in.nextActionAt(),caseId);jdbc.update("UPDATE customer_requests SET status=?,updated_at=NOW() WHERE id=(SELECT request_id FROM workflow_cases WHERE id=?)",requestStatus(in.stage()),caseId);event(caseId,"STAGE_CHANGED",old.stage(),in.stage(),in.note(),actor.id());syncTags(caseId);audit(actor.id(),"workflow_case",caseId,"TRANSITION");return required(caseId);}
    @Transactional public void addManualTag(UUID caseId,UUID tagId,AuthPrincipal actor){required(caseId);Integer c=jdbc.queryForObject("SELECT COUNT(*) FROM tags WHERE id=? AND scope='CASE' AND is_active=TRUE",Integer.class,tagId);if(c==null||c==0)throw bad("برچسب معتبر نیست.");jdbc.update("INSERT INTO case_tags(case_id,tag_id,source,applied_by_user_id) VALUES (?,?,'MANUAL',?) ON CONFLICT(case_id,tag_id) DO UPDATE SET source='MANUAL',applied_by_user_id=EXCLUDED.applied_by_user_id",caseId,tagId,actor.id());event(caseId,"TAG_ADDED",null,null,null,actor.id());}
    @Transactional public void removeManualTag(UUID caseId,UUID tagId,AuthPrincipal actor){if(jdbc.update("DELETE FROM case_tags WHERE case_id=? AND tag_id=? AND source='MANUAL'",caseId,tagId)==0)throw bad("برچسب سیستمی یا ناموجود را نمی‌توان دستی حذف کرد.");event(caseId,"TAG_REMOVED",null,null,null,actor.id());}
    public List<TagRow> availableTags(){return jdbc.query("SELECT id,slug,label_fa,color_key,'AVAILABLE' source FROM tags WHERE scope='CASE' AND is_active=TRUE ORDER BY is_system,label_fa",(rs,n)->new TagRow(rs.getObject("id",UUID.class),rs.getString("slug"),rs.getString("label_fa"),rs.getString("color_key"),rs.getString("source")));}

    @Transactional public Map<String,Object> addSupplierQuote(UUID caseId,SupplierQuoteInput in,AuthPrincipal actor){CaseRow old=required(caseId);if(in.supplierName()==null||in.supplierName().isBlank()||in.currency()==null||in.unitPrice()==null)throw bad("نام تامین‌کننده، ارز و قیمت الزامی است.");UUID id=jdbc.queryForObject("INSERT INTO supplier_quotes(case_id,supplier_id,supplier_name_snapshot,country,currency,unit_price,quantity,foreign_transport,international_shipping,available_quantity,lead_days,valid_until,created_by_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",UUID.class,caseId,in.supplierId(),in.supplierName().trim(),in.country(),in.currency().toUpperCase(),in.unitPrice(),in.quantity()==null?BigDecimal.ONE:in.quantity(),zero(in.foreignTransport()),zero(in.internationalShipping()),in.availableQuantity(),in.leadDays(),in.validUntil(),actor.id());if(Set.of("REQUESTED","PRODUCT_CREATED","SOURCING").contains(old.stage()))jdbc.update("UPDATE workflow_cases SET stage='SUPPLIER_QUOTED',updated_at=NOW() WHERE id=?",caseId);event(caseId,"SUPPLIER_QUOTE_ADDED",old.stage(),"SUPPLIER_QUOTED","استعلام تامین‌کننده ثبت شد.",actor.id());syncTags(caseId);return jdbc.queryForMap("SELECT * FROM supplier_quotes WHERE id=?",id);}
    @Transactional public Map<String,Object> addCustomerQuote(UUID caseId,CustomerQuoteInput in,AuthPrincipal actor){CaseRow old=required(caseId);if(in.currency()==null||in.totalPrice()==null)throw bad("ارز و قیمت نهایی الزامی است.");String status=in.sendNow()?"SENT":"DRAFT";UUID id=jdbc.queryForObject("INSERT INTO customer_quotes(case_id,currency,supplier_cost,logistics_cost,customs_cost,bank_cost,local_cost,other_cost,markup_amount,discount_amount,tax_amount,exchange_rate,total_price,valid_until,status,created_by_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",UUID.class,caseId,in.currency().toUpperCase(),zero(in.supplierCost()),zero(in.logisticsCost()),zero(in.customsCost()),zero(in.bankCost()),zero(in.localCost()),zero(in.otherCost()),zero(in.markupAmount()),zero(in.discountAmount()),zero(in.taxAmount()),in.exchangeRate(),in.totalPrice(),in.validUntil(),status,actor.id());if(in.sendNow()){jdbc.update("UPDATE workflow_cases SET stage='CUSTOMER_QUOTED',updated_at=NOW() WHERE id=?",caseId);jdbc.update("UPDATE customer_requests SET status='QUOTED',updated_at=NOW() WHERE id=(SELECT request_id FROM workflow_cases WHERE id=?)",caseId);event(caseId,"CUSTOMER_QUOTE_SENT",old.stage(),"CUSTOMER_QUOTED","قیمت برای مشتری ارسال شد.",actor.id());syncTags(caseId);}else event(caseId,"CUSTOMER_QUOTE_DRAFTED",null,null,null,actor.id());return jdbc.queryForMap("SELECT * FROM customer_quotes WHERE id=?",id);}

    private CaseRow create(CreateRequest in,UUID actor,boolean site){if(in.requestText()==null||in.requestText().isBlank())throw bad("شرح درخواست الزامی است.");String source=site?"SITE":(in.source()==null?"OTHER":in.source().toUpperCase());if(!Set.of("SITE","PHONE","WHATSAPP","EMAIL","INSTAGRAM","OTHER").contains(source))throw bad("منبع نامعتبر است.");String priority=in.priority()==null?"NORMAL":in.priority().toUpperCase();if(!Set.of("LOW","NORMAL","HIGH","URGENT").contains(priority))throw bad("اولویت نامعتبر است.");UUID request=jdbc.queryForObject("INSERT INTO customer_requests(source,contact_name,contact_phone,contact_email,requested_part_number,request_text,vehicle_text,status,created_by_user_id) VALUES (?,?,?,?,?,?,?,'NEW',?) RETURNING id",UUID.class,source,in.contactName(),in.contactPhone(),in.contactEmail(),in.requestedPartNumber(),in.requestText().trim(),in.vehicleText(),actor);UUID caseId=jdbc.queryForObject("INSERT INTO workflow_cases(request_id,product_id,manager_user_id,priority) VALUES (?,?,?,?) RETURNING id",UUID.class,request,in.productId(),actor,priority);event(caseId,"REQUEST_CREATED",null,"REQUESTED",site?"ثبت درخواست از وب‌سایت":"ثبت درخواست داخلی",actor);syncTags(caseId);return required(caseId);}
    private CaseRow required(UUID id){return cases(null).stream().filter(c->c.id().equals(id)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"پرونده پیدا نشد."));}
    private CaseRow mapCase(ResultSet rs,int n)throws SQLException{UUID id=rs.getObject("id",UUID.class);Timestamp next=rs.getTimestamp("next_action_at");return new CaseRow(id,rs.getLong("case_no"),rs.getLong("request_no"),rs.getString("source"),rs.getString("contact_name"),rs.getString("contact_phone"),rs.getString("requested_part_number"),rs.getString("request_text"),rs.getString("vehicle_text"),rs.getObject("product_id",UUID.class),rs.getString("stage"),rs.getString("priority"),rs.getString("agreement_status"),next==null?null:next.toInstant(),rs.getString("notes"),rs.getTimestamp("updated_at").toInstant(),tags(id));}
    private List<TagRow> tags(UUID id){return jdbc.query("SELECT t.id,t.slug,t.label_fa,t.color_key,ct.source FROM case_tags ct JOIN tags t ON t.id=ct.tag_id WHERE ct.case_id=? ORDER BY ct.source DESC,t.label_fa",(rs,n)->new TagRow(rs.getObject("id",UUID.class),rs.getString("slug"),rs.getString("label_fa"),rs.getString("color_key"),rs.getString("source")),id);}
    private void syncTags(UUID id){Map<String,Object> m=jdbc.queryForMap("SELECT c.stage,r.source FROM workflow_cases c JOIN customer_requests r ON r.id=c.request_id WHERE c.id=?",id);String stage=(String)m.get("stage"),source=(String)m.get("source");jdbc.update("DELETE FROM case_tags WHERE case_id=? AND source='AUTOMATIC'",id);if("SITE".equals(source))apply(id,"site-request");if(Set.of("PRODUCT_CREATED","SOURCING","SUPPLIER_QUOTED","INTERNAL_COSTED").contains(stage))apply(id,"sourcing");if("CUSTOMER_QUOTED".equals(stage))apply(id,"quote-sent");if(Set.of("CUSTOMER_AGREED","SUPPLIER_ORDERED","IN_TRANSIT","CUSTOMS","LOCAL_WAREHOUSE","READY_FOR_DELIVERY","DELIVERED","CLOSED").contains(stage))apply(id,"agreement");if("IN_TRANSIT".equals(stage))apply(id,"in-transit");if("CUSTOMS".equals(stage))apply(id,"customs");if(Set.of("DELIVERED","CLOSED").contains(stage))apply(id,"delivered");}
    private void apply(UUID id,String slug){jdbc.update("INSERT INTO case_tags(case_id,tag_id,source) SELECT ?,id,'AUTOMATIC' FROM tags WHERE slug=? ON CONFLICT(case_id,tag_id) DO UPDATE SET source='AUTOMATIC'",id,slug);}
    private void event(UUID id,String type,String from,String to,String note,UUID actor){jdbc.update("INSERT INTO workflow_events(case_id,event_type,from_stage,to_stage,note,created_by_user_id) VALUES (?,?,?,?,?,?)",id,type,from,to,note,actor);}
    private void audit(UUID actor,String entity,UUID id,String action){jdbc.update("INSERT INTO audit_log(actor_user_id,entity_type,entity_id,action) VALUES (?,?,?,?)",actor,entity,id.toString(),action);}
    private String requestStatus(String stage){return switch(stage){case "REQUESTED"->"NEW";case "CUSTOMER_QUOTED"->"QUOTED";case "CUSTOMER_AGREED","SUPPLIER_ORDERED","IN_TRANSIT","CUSTOMS","LOCAL_WAREHOUSE","READY_FOR_DELIVERY","DELIVERED"->"WON";case "CANCELLED"->"LOST";case "CLOSED"->"CLOSED";default->"IN_PROGRESS";};}
    private BigDecimal zero(BigDecimal v){return v==null?BigDecimal.ZERO:v;}private long count(String sql){Long v=jdbc.queryForObject(sql,Long.class);return v==null?0:v;}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
